function selectedTexts(id){const el=$(id);return el?[...el.selectedOptions].map(o=>o.textContent.trim()).filter(Boolean):[]}
function vehicleStatusOptions(selected='available'){const opts=[['available','متاحة'],['working','شغالة'],['maintenance','بها عطل'],['inactive','غير نشطة']];return opts.map(x=>'<option value="'+x[0]+'" '+(String(selected)===x[0]?'selected':'')+'>'+x[1]+'</option>').join('')}
function updateVehicleFaultFields(){const show=employeeValue('vehStatus')==='maintenance';if($('vehicleFaultFields'))$('vehicleFaultFields').classList.toggle('hidden',!show)}


function openOperation(op){if(op==='site_entry')openTomorrowSiteEntry();else if(op==='employee')openEmployeeForm();else if(op==='company_vehicle')openCompanyVehicleForm();else if(op==='leave')openLeaveForm(false);else if(op==='mission')openLeaveForm(true);else if(op==='sick_leave')openSickLeaveForm();else if(op==='extend_leave')openExtendLeaveForm();else if(op==='cancel_leave')openCancelLeaveForm()}

function tomorrowDutyRule(employee){
  const job=String(employee.job_title||employee.job||employee.position||'').trim();
  const department=String(employee.department||'').trim();
  const text=(job+' '+department).toLowerCase();
  const isManager=/مدير\s*(الموقع|موقع|المشروع|مشروع|الداتا\s*(انليزيز|أناليسز|اناليسز|تحليل البيانات)|الجود[هة]|جود[هة])|site\s*manager|project\s*manager|data\s*analysis\s*manager|quality\s*manager/i.test(text);
  const isQuality=/جود[هة]|quality/i.test(text);
  if(isManager)return{fixed:true,value:L('إدارة ومتابعة أعمال الموقع','Site management and operational follow-up')};
  if(isQuality)return{fixed:true,value:L('أخذ العينات من الموقع','Collecting samples from the site')};
  return{fixed:false,value:''};
}
function syncTomorrowDutyRow(checkbox){
  const row=checkbox.closest('.tomorrow-person'),input=row&&row.querySelector('[data-tomorrow-duty]');
  if(!input)return;
  input.disabled=!checkbox.checked;
  row.classList.toggle('selected',checkbox.checked);
  if(!checkbox.checked&&!input.dataset.fixed)input.classList.remove('employee-invalid');
}
function openTomorrowSiteEntry(){
  const date=addDays(today(),1), employees=(DATA&&DATA.filters&&DATA.filters.employees)||[];
  const rows=employees.map(e=>{
    const rule=tomorrowDutyRule(e),fixed=rule.fixed?' data-fixed="1" readonly':'';
    const placeholder=rule.fixed?'':L('اكتب سبب دخوله ومهمته داخل الموقع غدًا','Write why this employee is entering and tomorrow’s site task');
    return '<label class="vehicle-choice tomorrow-person" data-employee-name="'+esc(e.name)+'"><div class="tomorrow-person-head"><input type="checkbox" data-tomorrow-employee value="'+esc(e.id)+'"><span><b>'+esc(e.name)+'</b><small>'+esc((e.job_title||e.job||'—')+' — '+(e.mine||'—')+' — '+(e.department||'—'))+'</small></span></div><div class="tomorrow-duty-wrap"><label>'+L('داخل الموقع لعمل:','On site to:')+'</label><input class="input tomorrow-duty" data-tomorrow-duty value="'+esc(rule.value)+'" placeholder="'+esc(placeholder)+'"'+fixed+' disabled></div></label>';
  }).join('');
  const html='<div class="permission-note">'+L('اختر الأشخاص الذين سيتوجهون إلى المنجم غدًا، وحدد مهمة كل موظف. موظفو الجودة تُسجل مهمتهم تلقائيًا «أخذ العينات من الموقع»، والوظائف الإدارية المحددة تُسجل لها مهمة المتابعة تلقائيًا. التاريخ: ','Choose employees going to the mine tomorrow and specify each person’s task. Quality staff and specified management roles receive an automatic task. Date: ')+'<b>'+date+'</b>.</div><div class="tomorrow-toolbar"><button class="btn ghost" type="button" id="selectAllTomorrow">'+L('تحديد الكل','Select all')+'</button><button class="btn ghost" type="button" id="clearTomorrow">'+L('إلغاء التحديد','Clear selection')+'</button><span id="tomorrowSelectedCount">0</span></div><div class="vehicle-choice-grid tomorrow-grid">'+(rows||'<div class="empty">'+L('لا يوجد موظفون متاحون','No employees available')+'</div>')+'</div>';
  renderOperationForm(L('دخول الموقع غدًا','Tomorrow site entry'),html,'<button class="btn ghost" id="backOps">'+L('إغلاق','Close')+'</button><button class="btn primary" id="saveTomorrowEntry">'+L('إرسال إلى Google Sheets','Send to Google Sheets')+'</button>');
  const update=()=>{const selected=[...document.querySelectorAll('[data-tomorrow-employee]:checked')];document.querySelectorAll('[data-tomorrow-employee]').forEach(syncTomorrowDutyRow);const el=$('tomorrowSelectedCount');if(el)el.textContent=L('تم اختيار ','Selected ')+selected.length+L(' موظف',' employees')};
  document.querySelectorAll('[data-tomorrow-employee]').forEach(x=>x.addEventListener('change',update));
  $('selectAllTomorrow').onclick=()=>{document.querySelectorAll('[data-tomorrow-employee]').forEach(x=>x.checked=true);update()};
  $('clearTomorrow').onclick=()=>{document.querySelectorAll('[data-tomorrow-employee]').forEach(x=>x.checked=false);update()};
  $('backOps').onclick=closeModal;
  $('saveTomorrowEntry').onclick=async()=>{try{
    const selected=[...document.querySelectorAll('[data-tomorrow-employee]:checked')];
    if(!selected.length)throw new Error(L('اختر موظفًا واحدًا على الأقل.','Select at least one employee.'));
    let firstInvalid=null;
    const records=selected.map(box=>{
      const row=box.closest('.tomorrow-person'),input=row.querySelector('[data-tomorrow-duty]'),duty=String(input.value||'').trim();
      input.classList.remove('employee-invalid');
      if(!duty){input.classList.add('employee-invalid');if(!firstInvalid)firstInvalid={input,name:row.dataset.employeeName||''};}
      return{employee_id:box.value,date,final_status:'on_site',assigned_vehicle_id:'',pickup_point:'',notes:L('سبب دخول الموقع غدًا: ','Tomorrow site-entry task: ')+duty};
    });
    if(firstInvalid){firstInvalid.input.focus();firstInvalid.input.scrollIntoView({behavior:'smooth',block:'center'});throw new Error(L('اكتب سبب دخول ومهمة الموظف: ','Enter the site-entry reason and task for: ')+firstInvalid.name);}
    showLoader(L('جارٍ إرسال دخول الموقع إلى Google Sheets...','Sending site entry to Google Sheets...'));
    for(let i=0;i<records.length;i+=8)await payloadApi('savedailyentries',{records:records.slice(i,i+8),rebuild:i+8>=records.length});
    closeModal();toast(L('تم تسجيل دخول الموقع غدًا ومهام الموظفين لعدد '+selected.length+' موظف.','Tomorrow site entry and tasks saved for '+selected.length+' employees.'));await loadData(true)
  }catch(e){toast(e.message,true)}finally{hideLoader()}};
  update();
}

function openDailyEditor(){const existing=new Map((DATA.charts.employee_status||[]).map(r=>[r.employee_id,r]));const rows=(DATA.filters.employees||[]).map(e=>{const r=existing.get(e.id)||{};return'<div class="daily-row" data-employee="'+esc(e.id)+'"><div><b>'+esc(e.name)+'</b><small>'+esc(e.department)+' — '+esc(e.mine)+'</small></div><select class="select dr-status">'+ALL_STATUSES.map(s=>'<option value="'+s+'" '+(normalizeStatusKey(r.status)===s?'selected':'')+'>'+STATUS[s]+'</option>').join('')+'</select><select class="select dr-vehicle"><option value="">بدون عربية</option>'+vehicleOptions().replace('value="'+esc(r.vehicle_id||'')+'"','value="'+esc(r.vehicle_id||'')+'" selected')+'</select><input class="input dr-pickup" placeholder="نقطة الركوب" value="'+esc(r.pickup_point||'')+'"><input class="input dr-note note" placeholder="ملاحظات"></div>'}).join('');renderOperationForm(L('إدخال حالة اليوم','Enter today status'),'<div class="permission-note">التاريخ: <b>'+$('cardDate').value+'</b> — داخل الموقع لا يعتمد إلا بعد تسجيل دخول الجبل.</div><div class="daily-editor">'+rows+'</div>','<button class="btn ghost" id="backOps">رجوع</button><button class="btn primary" id="saveDaily">حفظ الحالات</button>');$('backOps').onclick=operationMenu;$('saveDaily').onclick=saveDailyEntries}
async function saveDailyEntries(){const records=[...document.querySelectorAll('.daily-row')].map(row=>({employee_id:row.dataset.employee,date:$('cardDate').value,final_status:row.querySelector('.dr-status').value,assigned_vehicle_id:row.querySelector('.dr-vehicle').value,pickup_point:row.querySelector('.dr-pickup').value,notes:row.querySelector('.dr-note').value}));try{showLoader('جارٍ حفظ حالات الموظفين...');for(let i=0;i<records.length;i+=8)await payloadApi('savedailyentries',{records:records.slice(i,i+8),rebuild:i+8>=records.length});closeModal();toast('تم حفظ الحالات');await loadData(true)}catch(e){toast(e.message,true)}finally{hideLoader()}}

function employeeValue(id){const el=$(id);return el?String(el.value||'').trim():''}
function employeeBool(id){return employeeValue(id)==='true'}
function employeeFormSteps(){return[
{title:'البيانات الأساسية',hint:'اسم الموظف ورقم الهاتف وتاريخ التعيين'},
{title:'بيانات العمل',hint:'المناجم والقسم والوظيفة والتعاقد والوردية'},
{title:'النقل والسائق',hint:'سياسة دخول الجبل والسكن والعربيات التي يقودها'},
{title:'المراجعة',hint:'مراجعة البيانات قبل الحفظ'}
]}
function employeeClearErrors(){document.querySelectorAll('#inputActionForm .employee-invalid').forEach(el=>el.classList.remove('employee-invalid'));const box=$('employeeErrorBox');if(box){box.classList.add('hidden');box.innerHTML=''}}
function employeeMarkError(id,message,errors){const el=$(id);if(el)el.classList.add('employee-invalid');errors.push(message)}
function validateEmployeeStep(step,notify=true){employeeClearErrors();const errors=[];
 if(step===0){
  if(!employeeValue('empName'))employeeMarkError('empName','اسم الموظف مطلوب.',errors);
  const phone=employeeValue('empPhone');if(phone&&!/^[+0-9][0-9\s-]{7,18}$/.test(phone))employeeMarkError('empPhone','رقم الهاتف غير صحيح.',errors);
 }
 if(step===1){
  if(!selectedValues('empMines').length)employeeMarkError('empMines','اختر منجمًا أو موقعًا واحدًا على الأقل.',errors);
  if(!employeeValue('empDepartment'))employeeMarkError('empDepartment','القسم مطلوب.',errors);
  if(!employeeValue('empJob'))employeeMarkError('empJob','الوظيفة مطلوبة.',errors);
  if(employeeBool('empHasManager')&&!employeeValue('empManagerId'))employeeMarkError('empManagerId','اختر المدير المباشر من الأفراد المسجلين.',errors);
 }
 if(step===2){
  if(!employeeValue('empPolicy'))employeeMarkError('empPolicy','سياسة دخول الجبل مطلوبة.',errors);
  if(!employeeValue('empResidence'))employeeMarkError('empResidence','مكان السكن مطلوب.',errors);
  if(isApartmentResidence(employeeValue('empResidence'))){const expense=employeeValue('empDailyExpense');if(expense==='')employeeMarkError('empDailyExpense','اكتب المصروف اليومي للموظف في الشقة.',errors);else if(n(expense)<0)employeeMarkError('empDailyExpense','المصروف اليومي لا يمكن أن يكون أقل من صفر.',errors)}
  if(employeeBool('empIsDriver')&&!selectedVehicleDriverIds().length)employeeMarkError('empIsDriver','اختر عربية واحدة على الأقل يستطيع الموظف قيادتها.',errors);
 }
 if(errors.length){const box=$('employeeErrorBox');if(box){box.innerHTML='<b>راجع البيانات التالية:</b><ul>'+errors.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>';box.classList.remove('hidden');box.scrollIntoView({behavior:'smooth',block:'nearest'})}if(notify)toast(errors[0],true);return false}
 return true}
function isApartmentResidence(value){const normalized=String(value||'').replace(/رقم/g,'').replace(/\s+/g,' ').trim();return /^شقة\s*[123]$/.test(normalized)}
function updateEmployeeConditionalFields(){
 const hasManager=employeeBool('empHasManager');if($('employeeManagerField'))$('employeeManagerField').classList.toggle('hidden',!hasManager);if(!hasManager&&$('empManagerId'))$('empManagerId').value='';
 const isDriver=employeeBool('empIsDriver');if($('employeeDriverVehicles'))$('employeeDriverVehicles').classList.toggle('hidden',!isDriver);
 const apartment=isApartmentResidence(employeeValue('empResidence'));if($('employeeDailyExpenseField'))$('employeeDailyExpenseField').classList.toggle('hidden',!apartment);if($('empDailyExpense')){$('empDailyExpense').required=apartment;if(!apartment)$('empDailyExpense').value=''}
}
function generateTemporaryPassword(){const upper='ABCDEFGHJKLMNPQRSTUVWXYZ',lower='abcdefghijkmnopqrstuvwxyz',digits='23456789',symbols='!@#$%';const all=upper+lower+digits+symbols;const pick=s=>{if(window.crypto&&crypto.getRandomValues){const a=new Uint32Array(1);crypto.getRandomValues(a);return s[a[0]%s.length]}return s[Math.floor(Math.random()*s.length)]};let value=pick(upper)+pick(lower)+pick(digits)+pick(symbols);while(value.length<12)value+=pick(all);value=value.split('').sort(()=>Math.random()-.5).join('');if($('loginPassword')){$('loginPassword').value=value;$('loginPassword').type='text'}}
