function render(tab,d){
  // Render only the open section. The previous implementation rebuilt every
  // table on every response, which made the page heavy even when the user only
  // needed the plan screen.
  const active=tab||document.body.dataset.activeTab||'today';
  if(active==='attendance'){renderAttendance();renderLeaves()}
  else if(active==='employees')renderEmployees();
  else if(active==='activities')renderActivities();
  else if(active==='plans')renderPlans();
  else if(active==='expenses'){populateExpenseFilters();renderRentalNeeds();renderPeriods()}

  if($('addActivityBtn'))$('addActivityBtn').classList.toggle('hidden',!permitted('manage_activities'));
  if($('addEmployeeAdvancedBtn'))$('addEmployeeAdvancedBtn').classList.toggle('hidden',!permitted('manage_employees'));
  if($('addPlanBtn')){const allowed=permitted('manage_plans');$('addPlanBtn').classList.toggle('hidden',!allowed);$('addPlanBtn').disabled=!allowed;$('addPlanBtn').setAttribute('aria-disabled',allowed?'false':'true')}
  if($('generateExpenseAdvancedBtn'))$('generateExpenseAdvancedBtn').classList.toggle('hidden',!permitted('manage_expenses'));
}

