async function copyTextSafe(text,message){try{if(navigator.clipboard&&navigator.clipboard.writeText)await navigator.clipboard.writeText(text);else{const t=document.createElement('textarea');t.value=text;document.body.appendChild(t);t.select();document.execCommand('copy');t.remove()}toast(message||'تم النسخ')}catch(e){modal('تقرير البلان','<textarea class="textarea report-copy-area" readonly>'+esc(text)+'</textarea>','<button class="btn ghost" data-v42-close>إغلاق</button>');toast('تعذر النسخ التلقائي؛ انسخ التقرير من النافذة.',true)}}
